package mcphandlers

import mcp "github.com/mark3labs/mcp-go/mcp"

// ToolNamespace is the shared MCP tool namespace prefix. The graph engine's
// standalone MCP tools are exposed under the same stablenet_knowledge.context.*
// convention as the fused system server and the vector engine, so all three
// servers speak one tool-naming convention.
const ToolNamespace = "stablenet_knowledge.context."

// nsTool is mcp.NewTool with the shared namespace prefix applied to the tool
// name. Handlers pass the bare base name (e.g. "find_symbol") for readability;
// clients see the namespaced name (e.g. "stablenet_knowledge.context.find_symbol").
func nsTool(name string, opts ...mcp.ToolOption) mcp.Tool {
	return mcp.NewTool(ToolNamespace+name, opts...)
}

