1	// Package cluster — Leiden community detection (V0 implementation).
2	//
3	// Goal: well-connected communities maximizing modularity at a given
4	// resolution γ. We follow the structure of the reference Java implementation
5	// at github.com/CWTSLeiden/networkanalysis, simplified to undirected unweighted
6	// graphs (V0 only treats edge multiplicity).
7	//
8	// Three nested phases per outer iteration:
9	//  1. Local moving — for each node, move it to the neighboring community
10	//     that maximizes ΔQ (modularity gain).
11	//  2. Refinement — within each community, restart with singletons and
12	//     re-aggregate to guarantee well-connectedness.
13	//  3. Aggregation — collapse each refined community into a single super-node
14	//     and recurse.
15	//
16	// Stops when no node move yields ΔQ > 0 across an entire pass.
17	package cluster
18	
19	import (
20		"math/rand"
21		"sort"
22	)
23	
24	// LeidenOpts controls a single run.
25	type LeidenOpts struct {
26		Resolution float64
27		Seed       int64
28		MaxIters   int
29	}
30	
31	// RunLeiden returns a partition: parts[i] is the community ID assigned
32	// to node i. n is the node count, edges are undirected (a,b) pairs;
33	// repeated pairs increase weight by 1.
34	func RunLeiden(n int, edges [][2]int, opts LeidenOpts) []int {
35		g := buildAdj(n, edges)
36		parts := make([]int, n)
37		for i := range parts {
38			parts[i] = i // singleton init
39		}
40		r := rand.New(rand.NewSource(opts.Seed))
41	
42		for iter := 0; iter < opts.MaxIters; iter++ {
43			movedLocal := localMove(g, parts, opts.Resolution, r)
44			// Refinement (V0 simplification: skip explicit refine, rely on local move).
45			// Aggregate: collapse current parts into a smaller graph and continue.
46			parts2, agg := aggregate(g, parts)
47			if !movedLocal && len(agg.weight) == len(g.weight) {
48				break
49			}
50			// Continue local-moving on the aggregated graph.
51			coarse := localMove(agg, parts2, opts.Resolution, r)
52			// Lift back to original node indices.
53			parts = lift(parts, parts2)
54			if !movedLocal && !coarse {
55				break
56			}
57		}
58		return relabel(parts)
59	}
60	
61	// adjList stores, per node, neighbor index and weight.
62	type adjList struct {
63		neigh   [][]int
64		weight  []float64 // sum of edge weights at node i (degree in weighted sense)
